package com.portfolio.assetory.inquiry.repository;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.portfolio.assetory.inquiry.domain.InquiryMessage;
public interface InquiryMessageRepository extends JpaRepository<InquiryMessage,Long>{@Query("select m from InquiryMessage m join fetch m.sender where m.room.id=:roomId order by m.sentAt asc,m.id asc")List<InquiryMessage> findAllForRoom(@Param("roomId")Long roomId);@Modifying @Query("update InquiryMessage m set m.readAt=CURRENT_TIMESTAMP where m.room.id=:roomId and m.sender.id<>:userId and m.readAt is null")int markReadByRoomIdAndNotSender(@Param("roomId")Long roomId,@Param("userId")Long userId);}
